using namespace RISE::HyLIoS;
namespace {
int checks=0;
void Check(bool v,const char* message){++checks;if(!v)throw std::runtime_error(message);}
struct Sequence:RISE::ISampler{
 std::vector<double> values;std::size_t index=0;explicit Sequence(std::initializer_list<double> v):values(v){}
 double Get1D()override{if(index==values.size())throw std::runtime_error("script exhausted");return values[index++];}
 RISE::Point2 Get2D()override{return {Get1D(),Get1D()};}
};
struct Random:RISE::ISampler{std::uint64_t bits,draws=0;explicit Random(std::uint64_t b):bits(b){}
 double Get1D()override{++draws;bits+=0x9e3779b97f4a7c15ULL;auto z=bits;z=(z^(z>>30))*0xbf58476d1ce4e5b9ULL;z=(z^(z>>27))*0x94d049bb133111ebULL;z^=z>>31;return static_cast<double>(z>>11)*0x1p-53;}
 RISE::Point2 Get2D()override{return {Get1D(),Get1D()};}
};
std::array<ForwardLayer,6> Layers(){std::array<ForwardLayer,6> l{};for(auto& x:l)x={.001,0,1,{}};return l;}
HyLIoSForwardTransport Kernel(std::array<ForwardLayer,6> l,double nm=1400,double fiber=0){return HyLIoSForwardTransport(l,nm,1,fiber,AbsorptionEstimator::Weighted,0,ForwardPlacementPolicy::FixedEventDiagnosticV1,ForwardPostScatterPolicy::DiscardAfterScatterV1);}
void Is(const ForwardState& s,ForwardAngularClass c,ForwardAngularReason r,const char* message){Check(s.AngularLineage().classification==c&&s.AngularLineage().reason==r,message);}
void Step(const HyLIoSForwardTransport& k,ForwardState& s,std::initializer_list<double> v){Sequence q(v);k.Advance(s,q,1);Check(s.Termination()==ForwardTermination::None,"script transition is successful");Check(q.index==q.values.size(),"script consumes exactly the law variates");}
ForwardState Enter(const HyLIoSForwardTransport& k){auto s=k.Begin({0,0,0},{.3,.4,1});auto e=s.PendingBoundary();k.ResumeBoundary(s,e.token,SampleSlabSmoothDielectric(e,.9));return s;}
ForwardState Particle(const HyLIoSForwardTransport& k,double projected=0){auto s=k.Begin({0,0,0},{0,0,1});auto e=s.PendingBoundary();k.ResumeBoundary(s,e.token,SampleSlabSmoothDielectric(e,.9));Step(k,s,{.3});Step(k,s,{.5,0,projected,0});Check(s.Phase()==ForwardPhase::ParticleChord,"independent particle entry reached");return s;}
std::array<ForwardLayer,6> Particles(double ior){auto l=Layers();l[0].organelle=ForwardOrganelle{ForwardOrganization::IndividualSpheroids,.2,.0001,.0001,0,ior};return l;}
constexpr auto Planar=ForwardAngularClass::KnownPlanarMirrorEligible,AC=ForwardAngularClass::AbsolutelyContinuous,Unknown=ForwardAngularClass::UnclassifiedSingular;
void PlanarControls(){
 auto layers=Layers();layers[0].realIOR=1.5;auto k=Kernel(layers);auto s=k.Begin({0,0,0},{.3,.4,1});
 Is(s,Planar,ForwardAngularReason::InitialPlanar,"launch is planar eligibility");Check(s.ReturnedAtomMap()==ForwardReturnedAtomMap::None,"pending launch is not returned atomic mass");
 auto e=s.PendingBoundary();const auto incoming=e.incidentDirection;auto decision=SampleSlabSmoothDielectric(e,0);Check(decision.angularLaw==SlabBoundaryAngularLaw::PlanarDielectric,"smooth helper stamps its law");k.ResumeBoundary(s,e.token,decision);
 Check(s.Termination()==ForwardTermination::ExternalReflection&&s.ReturnedAtomMap()==ForwardReturnedAtomMap::PlanarSameExteriorMirror,"oblique smooth reflection exposes analytic mirror map");
 const SlabVector wi{-incoming.x,incoming.y,incoming.z},wo{s.Direction().x,-s.Direction().y,-s.Direction().z};
 Check(std::abs(wo.x+wi.x)<1e-15&&std::abs(wo.y+wi.y)<1e-15&&std::abs(wo.z-wi.z)<1e-15,"nonzero azimuth right-handed adapter agrees with local mirror map");
 auto inner=Enter(k);Step(k,inner,{0});Check(inner.Layer()==0,"internal Fresnel reflected in top layer");Is(inner,Planar,ForwardAngularReason::InitialPlanar,"internal smooth reflection preserves planar eligibility");Sequence none{};k.Advance(inner,none,1);Check(inner.HasPendingBoundary(),"return surface encountered before diffuse bottom");e=inner.PendingBoundary();k.ResumeBoundary(inner,e.token,SampleSlabSmoothDielectric(e,.99));Check(inner.ReturnedAtomMap()==ForwardReturnedAtomMap::PlanarSameExteriorMirror,"subsurface return before randomization has same mirror map");
 auto unknown=k.Begin({0,0,0},{0,0,1});e=unknown.PendingBoundary();decision=SampleSlabSmoothDielectric(e,0);decision.angularLaw=SlabBoundaryAngularLaw::Unclassified;k.ResumeBoundary(unknown,e.token,decision);Is(unknown,Unknown,ForwardAngularReason::UntypedBoundary,"identical numeric smooth direction without law metadata stays unknown");Check(unknown.ReturnedAtomMap()==ForwardReturnedAtomMap::None,"untyped external return is not guessed mirror");
 for(int stop=0;stop<2;++stop){auto live=k.Begin({0,0,0},{0,0,1});if(stop)k.StopForBudget(live);else k.Cancel(live);Is(live,Planar,ForwardAngularReason::InitialPlanar,"stop preserves in-flight law eligibility");Check(live.Weight()==1&&live.ReturnedAtomMap()==ForwardReturnedAtomMap::None,"unresolved live power is never returned atom");}
 auto zero=k.Begin({0,0,0},{0,0,1});e=zero.PendingBoundary();decision=SampleSlabSmoothDielectric(e,0);decision.weightMultiplier=0;k.ResumeBoundary(zero,e.token,decision);Check(zero.Termination()==ForwardTermination::ZeroWeight&&zero.ReturnedAtomMap()==ForwardReturnedAtomMap::None,"zero-return event exposes no atomic component");
}
void ParticleControls(){
 auto matched=Kernel(Particles(1));auto s=Particle(matched);Step(matched,s,{.9});Is(s,Planar,ForwardAngularReason::InitialPlanar,"matched material index preserves exact angular identity despite geometry draws");Step(matched,s,{});Is(s,Planar,ForwardAngularReason::InitialPlanar,"zero exponential width preserves identity and consumes no draws");
 auto mirrorLayers=Particles(1);mirrorLayers[1].realIOR=1.5;auto mk=Kernel(mirrorLayers);auto mirrorParticle=Particle(mk);Step(mk,mirrorParticle,{.9});Step(mk,mirrorParticle,{});Step(mk,mirrorParticle,{.999999,0});Step(mk,mirrorParticle,{.999999});Check(mirrorParticle.HasPendingBoundary(),"matched particle then planar reflection returns to exterior boundary before diffuse bottom");auto me=mirrorParticle.PendingBoundary();mk.ResumeBoundary(mirrorParticle,me.token,SampleSlabSmoothDielectric(me,.9));Check(mirrorParticle.ReturnedAtomMap()==ForwardReturnedAtomMap::PlanarSameExteriorMirror,"matched index plus zero kick retains returned mirror atom through stochastic geometry");
 auto k=Kernel(Particles(2));auto first=Particle(k);Step(k,first,{.9});Is(first,AC,ForwardAngularReason::ProjectedParticleTransmission,"independent projected first transmission has AC ensemble normal law");
 auto reflected=Particle(k,.6);Step(k,reflected,{0});Is(reflected,AC,ForwardAngularReason::ProjectedParticleReflection,"first reflected event has AC projected-normal map before cosine");Check(reflected.Phase()==ForwardPhase::ReflectedPerturbation,"first reflection is a resumable intermediate state");
 auto copy=reflected;Sequence empty{};k.Advance(copy,empty,0);Is(copy,AC,ForwardAngularReason::ProjectedParticleReflection,"zero quantum and copied state retain intermediate proof");
 bool rejected=false,accepted=false;for(int j=0;j<32;++j){auto trial=reflected;Sequence q{.99,static_cast<double>(j)/32};k.Advance(trial,q,1);Check(q.index==2&&trial.Termination()==ForwardTermination::None,"cosine proposal has unchanged two draws");if(trial.Phase()==ForwardPhase::ReflectedPerturbation){rejected=true;Is(trial,AC,ForwardAngularReason::ProjectedParticleReflection,"rejected cosine leaves first-reflection classification unchanged");}else{accepted=true;Is(trial,AC,ForwardAngularReason::ReflectedCosine,"accepted cosine refreshes AC separately from reflection");}}
 Check(rejected&&accepted,"off-centre reflected fixture covers both cosine branches");
 auto retained=Particle(k);Step(k,retained,{0});Step(k,retained,{0,0});Is(retained,AC,ForwardAngularReason::ReflectedCosine,"accepted cosine before retained chord is AC");Step(k,retained,{.9});Is(retained,Unknown,ForwardAngularReason::RetainedCurvedTransmission,"later retained curved transmission is explicitly unproved");Step(k,retained,{});Is(retained,Unknown,ForwardAngularReason::RetainedCurvedTransmission,"zero final width cannot repair unknown geometry transform");
 auto kick=Kernel(Particles(2),550);auto pending=Particle(kick);Step(kick,pending,{0});Step(kick,pending,{0,0});Step(kick,pending,{.9});Is(pending,Unknown,ForwardAngularReason::RetainedCurvedTransmission,"unknown retained transform before finite-width proposal");
 Random random(91);for(int j=0;j<1000&&pending.Phase()==ForwardPhase::ForwardPerturbation;++j)kick.Advance(pending,random,1);Is(pending,AC,ForwardAngularReason::ExponentialForward,"accepted nonzero exponential refreshes AC");
 auto complex=Layers();complex[0].organelle=ForwardOrganelle{ForwardOrganization::ExplicitComplexPackV1,.2,.0001,.0001,0,2,.0001,1};auto ck=Kernel(complex);auto child=ck.Begin({0,0,0},{0,0,1});auto e=child.PendingBoundary();ck.ResumeBoundary(child,e.token,SampleSlabSmoothDielectric(e,.9));Step(ck,child,{.3});Step(ck,child,{0,0});Step(ck,child,{.5,.5,.5,.5,0});Step(ck,child,{});Step(ck,child,{.9});Is(child,Unknown,ForwardAngularReason::RetainedCurvedTransmission,"complex child refraction is conservative unclassified even coincident envelope");Step(ck,child,{});Is(child,Unknown,ForwardAngularReason::RetainedCurvedTransmission,"envelope crossing adds no Snell event or proof");
 complex[0].organelle->realIOR=1;auto identityComplex=Kernel(complex);auto ci=identityComplex.Begin({0,0,0},{0,0,1});e=ci.PendingBoundary();identityComplex.ResumeBoundary(ci,e.token,SampleSlabSmoothDielectric(e,.9));Step(identityComplex,ci,{.3});Step(identityComplex,ci,{0,0});Step(identityComplex,ci,{.5,.5,.5,.5,0});Step(identityComplex,ci,{});Step(identityComplex,ci,{.9});Step(identityComplex,ci,{});Step(identityComplex,ci,{});Is(ci,Planar,ForwardAngularReason::InitialPlanar,"matched child transmission and zero complex kick retain identity");
 complex[0].organelle->childCount=0;auto ek=Kernel(complex,550);auto emptyState=ek.Begin({0,0,0},{0,0,1});e=emptyState.PendingBoundary();ek.ResumeBoundary(emptyState,e.token,SampleSlabSmoothDielectric(e,.9));Step(ek,emptyState,{.3});Step(ek,emptyState,{0,0});Step(ek,emptyState,{});Is(emptyState,Planar,ForwardAngularReason::InitialPlanar,"empty complex geometry does not invent angular scattering at 550nm");
}
void RandomLawControls(){auto k=Kernel(Layers());auto s=Enter(k);for(int i=0;i<5;++i)Step(k,s,{.5});Step(k,s,{0,0});Is(s,AC,ForwardAngularReason::DiffuseBottom,"diffuse bottom law is continuous even realized normal direction");
 auto fiber=Kernel(Layers(),1400,1e8);auto p=Enter(fiber);for(int i=0;i<4;++i)Step(fiber,p,{.5});Step(fiber,p,{.5});Is(p,Planar,ForwardAngularReason::InitialPlanar,"fiber event clock alone does not randomize direction");Step(fiber,p,{.5,.999999});Is(p,Planar,ForwardAngularReason::InitialPlanar,"rejected Rayleigh proposal preserves lineage");Step(fiber,p,{.999999,0,0});Is(p,AC,ForwardAngularReason::FiberRayleigh,"accepted Rayleigh refreshes AC");
}
void BoundaryControls(){auto l=Layers();l[0].realIOR=1.5;auto k=Kernel(l);
 for(double aspect:{0.,1.}){HyLIoSSurfaceBoundary boundary(aspect);auto s=k.Begin({0,0,0},{.3,.4,1});auto b=boundary.Begin(s.PendingBoundary());boundary.TrySample(b,0);if(aspect>0){Check(b.Phase()==SurfaceBoundaryPhase::NormalProposal,"nonzero fold pins reflected branch before angular proposal");bool unavailable=false;try{b.Decision();}catch(const std::logic_error&){unavailable=true;}Check(unavailable,"pending normal proposal cannot expose a completed angular proof");boundary.TrySample(b,.5,0,1-0x1p-53);Check(b.Phase()==SurfaceBoundaryPhase::NormalProposal,"rejected normal proposal remains pending");Is(s,Planar,ForwardAngularReason::InitialPlanar,"unaccepted boundary proposal never changes kernel lineage");for(int j=0;j<1000&&b.Phase()!=SurfaceBoundaryPhase::Ready;++j)boundary.TrySample(b,.999,static_cast<double>(j%32)/32,0);Check(b.Phase()==SurfaceBoundaryPhase::Ready,"fold accepted fixture ready");}
 const auto d=b.Decision();Check(d.angularLaw==(aspect==0?SlabBoundaryAngularLaw::PlanarDielectric:SlabBoundaryAngularLaw::IndependentFoldReflection),"boundary annotates exact zero or accepted nonzero reflected law");k.ResumeBoundary(s,s.PendingBoundary().token,d);Check(s.AngularLineage().classification==(aspect==0?Planar:AC),"fold reflection classification is based on authored law");Check((s.ReturnedAtomMap()!=ForwardReturnedAtomMap::None)==(aspect==0),"finite fold does not masquerade as mirror atom");}
 HyLIoSSurfaceBoundary fold(1);auto s=k.Begin({0,0,0},{0,0,1});auto b=fold.Begin(s.PendingBoundary());fold.TrySample(b,.9);Check(b.Decision().angularLaw==SlabBoundaryAngularLaw::PlanarDielectric,"nonzero folds leave macro transmission planar");k.ResumeBoundary(s,s.PendingBoundary().token,b.Decision());Is(s,Planar,ForwardAngularReason::InitialPlanar,"macro transmission cannot invent fold randomization");
}
void ResumeControls(){
 for(int config=0;config<4;++config){auto l=Layers();if(config>0)l=Particles(config==1?1:2);auto k=Kernel(l,config>1?550:1400,config==0?1e5:0);HyLIoSSurfaceBoundary surface(config==3?1:0);
 for(int seed=0;seed<64;++seed){Random a(seed+123),b(seed+123);auto one=k.Begin({0,0,0},{.3,.4,1}),many=one;
 auto run=[&](ForwardState& state,Random& rng,std::size_t quantum){while(state.Termination()==ForwardTermination::None){if(state.HasPendingBoundary()){auto boundary=surface.Begin(state.PendingBoundary());while(boundary.Phase()!=SurfaceBoundaryPhase::Ready){if(boundary.Phase()==SurfaceBoundaryPhase::Branch)surface.TrySample(boundary,rng.Get1D());else{const double u=rng.Get1D(),v=rng.Get1D(),acceptance=rng.Get1D();surface.TrySample(boundary,u,v,acceptance);}}k.ResumeBoundary(state,state.PendingBoundary().token,boundary.Decision());}else{k.Advance(state,rng,std::min<std::size_t>(quantum,2000-state.Counters().workUnits));if(state.Counters().workUnits>=2000)k.StopForBudget(state);}}};
 run(one,a,1);run(many,b,37);Check(a.bits==b.bits&&a.draws==b.draws,"quantum partition preserves complete RNG state");Check(one.AngularLineage().classification==many.AngularLineage().classification&&one.AngularLineage().reason==many.AngularLineage().reason&&one.ReturnedAtomMap()==many.ReturnedAtomMap(),"copied/resumed quantum partitions preserve complete lineage");Check(one.Direction().x==many.Direction().x&&one.Direction().y==many.Direction().y&&one.Direction().z==many.Direction().z&&one.Weight()==many.Weight()&&one.Counters().workUnits==many.Counters().workUnits&&one.Termination()==many.Termination(),"quantum partition preserves terminal physical state");}
 }
 auto numericalKernel=Kernel(Layers());auto numerical=numericalKernel.Begin({0,0,0},{0,0,1});auto event=numerical.PendingBoundary();auto doubled=SampleSlabSmoothDielectric(event,.9);doubled.weightMultiplier=2;numericalKernel.ResumeBoundary(numerical,event.token,doubled);Random path(765);while(!numerical.HasPendingBoundary()&&numerical.Termination()==ForwardTermination::None)numericalKernel.Advance(numerical,path,100);Check(numerical.HasPendingBoundary(),"numerical boundary fixture reaches diffuse return");event=numerical.PendingBoundary();auto overflow=SampleSlabSmoothDielectric(event,.9);overflow.weightMultiplier=std::numeric_limits<double>::max();const auto law=numerical.AngularLineage();overflow.angularLaw=SlabBoundaryAngularLaw::Unclassified;numericalKernel.ResumeBoundary(numerical,event.token,overflow);Check(numerical.Termination()==ForwardTermination::NumericalFailure&&numerical.Weight()==2&&numerical.AngularLineage().classification==law.classification&&numerical.AngularLineage().reason==law.reason&&numerical.ReturnedAtomMap()==ForwardReturnedAtomMap::None,"numeric power failure preserves live weight and predecision lineage despite unclassified proposal");
 auto k=Kernel(Particles(2),550);auto pending=Particle(k);Step(k,pending,{0});Step(k,pending,{0,0});Step(k,pending,{.9});const auto prior=pending.AngularLineage();Sequence invalid{1};k.Advance(pending,invalid,1);Check(pending.Termination()==ForwardTermination::InvalidSample&&pending.AngularLineage().classification==prior.classification&&pending.AngularLineage().reason==prior.reason&&pending.ReturnedAtomMap()==ForwardReturnedAtomMap::None,"invalid random input preserves preproposal lineage without returned mass");
 auto live=Particle(k);Step(k,live,{0});const auto before=live.AngularLineage();k.Cancel(live);Check(live.Weight()==1&&live.AngularLineage().classification==before.classification&&live.AngularLineage().reason==before.reason&&live.ReturnedAtomMap()==ForwardReturnedAtomMap::None,"cancelled intermediate first reflection retains law metadata and live weight");
}

}
int main(){try{PlanarControls();ParticleControls();RandomLawControls();BoundaryControls();ResumeControls();std::cout<<"PASS "<<checks<<" angular lineage checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
